const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;padding:10px;display:flex;flex-direction:column;gap:6px;overflow:hidden;background:transparent;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"],.card[data-size=\"3x6\"]{padding:8px;gap:5px}\n.hd{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.hdt{flex:1;min-width:0}\n.hd h1{margin:0;font-size:14px;line-height:1.25;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"3x3\"] .hd h1,.card[data-size=\"3x6\"] .hd h1{font-size:13px}\n.meta{font-size:10.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tabs{flex:none;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1.15fr);gap:4px}\n.tabs .btn{padding:2px 4px;min-height:26px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.body{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column}\n.card[data-size=\"6x3\"] .body{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:8px}\n.card[data-size=\"6x6\"] .body{display:grid;grid-template-rows:minmax(0,3fr) minmax(0,2fr);gap:8px}\n.pane{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:4px}\n.ph{flex:none;display:flex;align-items:center;flex-wrap:wrap;gap:4px;min-width:0}\n.pt{flex:1;min-width:0;font-weight:700;font-size:12px}\n.segs{display:flex;gap:4px}\n.push{margin-left:auto}\n.list{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.btn{flex:none;min-width:0;min-height:26px;padding:3px 9px;font:inherit;font-size:12px;line-height:1.2;color:var(--ink);background:var(--button-paper,var(--panel-paper));border:1px solid var(--line);border-radius:8px;cursor:pointer;white-space:nowrap}\n.btn.sm{min-height:22px;padding:1px 7px;font-size:11px;border-radius:7px}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.on{background:var(--soft);border-color:var(--accent);font-weight:700}\n.btn[disabled]{opacity:.5;cursor:not-allowed}\n.btn:focus-visible,.item:focus-visible,.inp:focus-visible,.lnk:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.item{flex:none;min-width:0;display:flex;flex-direction:column;gap:2px;padding:6px 8px;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;cursor:pointer}\n.row1{display:flex;align-items:center;gap:6px;min-width:0}\n.row2{display:flex;align-items:center;gap:4px;min-width:0;margin-top:2px}\n.cnt{flex:1}\n.nm{flex:1;min-width:0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dt{flex:none;font-size:10px;color:var(--muted)}\n.dot{flex:none;width:8px;height:8px;border-radius:50%;background:var(--accent)}\n.rec.no .dot{background:transparent;border:1.5px solid var(--muted)}\n.rec.no .nm{font-weight:500;color:var(--muted)}\n.sub{min-width:0;font-size:10.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chg,.cmp{min-width:0;font-size:11px;overflow:hidden;overflow-wrap:anywhere;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2}\n.cmp{color:var(--muted)}\n.from{min-width:0;font-size:10.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.lnk{color:var(--accent);text-decoration:underline;overflow-wrap:anywhere}\n.muted{color:var(--muted)}\n.chip{flex:none;padding:0 7px;font-size:10px;line-height:17px;color:var(--ink);background:var(--soft);border-radius:999px}\n.sr.paused{border-style:dashed}\n.sr.paused .chip{background:transparent;border:1px solid var(--muted)}\n.note{flex:none;font-size:10.5px;color:var(--muted)}\n.empty{flex:none;display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:8px;font-size:11.5px;color:var(--muted);border:1px dashed var(--line);border-radius:10px}\n.err{flex:none;padding:4px 8px;font-size:11px;font-weight:600;color:var(--ink);background:var(--soft);border:1px solid var(--accent);border-radius:8px}\n.warn{flex:none;font-weight:700;font-size:12.5px}\n.screen p{margin:0;font-size:11.5px;overflow-wrap:anywhere}\n\n.screen{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.bar{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.ttl{flex:1;min-width:0;font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.scroll>*{flex:none}\n.foot{flex:none;display:flex;gap:6px}\n.foot .btn{flex:1}\n.acts{display:flex;flex-wrap:wrap;gap:4px}\n.box{display:flex;flex-direction:column;gap:3px;padding:6px 8px;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px}\n.kv{display:grid;grid-template-columns:44px minmax(0,1fr);gap:6px;font-size:11.5px}\n.k{color:var(--muted);font-size:10.5px;padding-top:1px}\n.v{min-width:0;overflow-wrap:anywhere}\n.confirm{display:flex;flex-direction:column;gap:6px;padding:6px 8px;font-size:11.5px;font-weight:600;background:var(--soft);border:1px solid var(--accent);border-radius:10px}\n.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:6px}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0}\n.fld.wide{grid-column:1/-1}\n.lb{font-size:10.5px;color:var(--muted)}\n.inp{display:block;width:100%;min-width:0;min-height:26px;padding:4px 6px;font:inherit;font-size:12px;color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:7px}\ntextarea.inp{min-height:54px;resize:vertical}\n.card[data-size=\"6x3\"] .scroll{padding-bottom:2px}\n.card[data-size=\"6x6\"] .item,.card[data-size=\"6x6\"] .box{padding:8px 10px}\n";
var FREQS=[{value:'daily',label:'每天'},{value:'3days',label:'每 3 天'},{value:'weekly',label:'每周'},{value:'biweekly',label:'每两周'},{value:'monthly',label:'每月'}];
function freqLabel(v){for(var i=0;i<FREQS.length;i++){if(FREQS[i].value===v)return FREQS[i].label;}return '未设置';}
function hostOf(u){return String(u||'').replace(/^https?:\/\//i,'').replace(/^www\./i,'').split(/[\/?#]/)[0];}
function isUrl(u){return /^https?:\/\/[^\s\/.]+\.[^\s]+$/i.test(u||'');}
function isDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(d||'');}
function norm(s){var o=s||{};return {sources:Array.isArray(o.sources)?o.sources:[],records:Array.isArray(o.records)?o.records:[]};}
function sortRecs(list){return list.map(function(r,i){return [r,i];}).sort(function(a,b){if(a[0].date!==b[0].date)return a[0].date<b[0].date?1:-1;return b[1]-a[1];}).map(function(x){return x[0];});}
function latestUpdate(records,sid,date){var c=records.filter(function(r){return r.sid===sid&&r.kind==='update'&&(!date||r.date<=date);});return c.length?sortRecs(c)[0]:null;}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  while(root.firstChild)root.removeChild(root.firstChild);
  const size=ctx.size||root.getAttribute('data-size')||'3x3';
  const wide=size.charAt(0)==='6';
  const S=norm(state);
  const recs=sortRecs(S.records);
  const srcById={};
  S.sources.forEach(function(x){srcById[x.id]=x;});
  if(!ui.tab)ui.tab='feed';
  if(!ui.filter)ui.filter='all';
  const nUp=recs.filter(function(r){return r.kind==='update';}).length;
  const nPaused=S.sources.filter(function(x){return x.paused;}).length;

  function h(tag,attrs,kids){
    return el.apply(null,[tag,attrs||{}].concat((kids||[]).filter(function(k){return k!==null&&k!==undefined&&k!==false;})));
  }
  function btn(label,onclick,cls,opt){
    const a={class:'btn'+(cls?' '+cls:''),type:'button',onclick:onclick};
    if(opt){for(var k in opt){if(k==='disabled'){if(opt[k])a.disabled=true;}else{a[k]=opt[k];}}}
    return h('button',a,[label]);
  }
  function act(fn){
    return {role:'button',tabindex:'0',onclick:function(){fn();},onkeydown:function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}}};
  }
  function go(screen,draft){
    ui.screen=screen;ui.draft=draft===undefined?null:draft;ui.err=null;ui.msg=null;ui.confirm=null;redraw();
  }
  function keep(extra){
    return Object.assign({tab:ui.tab,filter:ui.filter,screen:null,draft:null,err:null,msg:null,confirm:null,saving:false},extra||{});
  }
  function srcName(r){
    const x=srcById[r.sid];
    return x?x.name:(r.sname||'来源')+'（已删除）';
  }
  function link(url,label){
    if(!isUrl(url))return h('span',{class:'muted'},[url||'未填写']);
    return h('a',{class:'lnk',href:url,target:'_blank',rel:'noopener noreferrer',title:url,onclick:function(e){e.stopPropagation();}},[label||hostOf(url)]);
  }
  function kv(k,v){
    return h('div',{class:'kv'},[h('span',{class:'k'},[k]),h('span',{class:'v'},[v])]);
  }
  function empty(text,action){
    return h('div',{class:'empty'},[h('div',{},[text]),action]);
  }
  function togglePause(id){
    update(function(s){
      const n=norm(s);
      return Object.assign({},s,{sources:n.sources.map(function(x){return x.id===id?Object.assign({},x,{paused:!x.paused}):x;})});
    }).catch(function(){ui.msg='暂停状态没有保存成功，请重试';redraw();});
  }


  function recItem(r,from){
    const isUp=r.kind==='update';
    const prevLine=isUp?(r.prev?'上次：'+(r.prev.title||'—'):'首次登记，作为对比基线'):(r.prev?'最近一次更新：'+(r.prev.title||'—'):null);
    return h('div',Object.assign({class:'item rec '+(isUp?'up':'no')},act(function(){go({t:'rec',id:r.id,from:from||null});})),[
      h('div',{class:'row1'},[
        h('span',{class:'dot','aria-hidden':'true'}),
        h('span',{class:'nm'},[isUp?(r.title||'有更新'):'无更新']),
        h('span',{class:'dt'},[r.date])
      ]),
      h('div',{class:'sub'},[srcName(r)+(isUp?'':' · 本次检查未发现变化')]),
      isUp&&r.changes?h('div',{class:'chg'},[r.changes]):null,
      prevLine?h('div',{class:'cmp'},[prevLine]):null,
      r.link?h('div',{class:'from'},['出处 ',link(r.link)]):null
    ]);
  }
  function srcItem(x){
    const n=S.records.filter(function(r){return r.sid===x.id;}).length;
    return h('div',Object.assign({class:'item sr'+(x.paused?' paused':'')},act(function(){go({t:'src',id:x.id});})),[
      h('div',{class:'row1'},[
        h('span',{class:'nm'},[x.name]),
        h('span',{class:'chip'},[x.paused?'已暂停':freqLabel(x.freq)])
      ]),
      h('div',{class:'sub'},[hostOf(x.url)]),
      x.focus?h('div',{class:'chg'},['关注：'+x.focus]):null,
      h('div',{class:'row2'},[
        h('span',{class:'sub cnt'},[n+' 条记录']),
        btn(x.paused?'恢复':'暂停',function(e){e.stopPropagation();togglePause(x.id);},'sm'),
        btn('查一次',function(e){e.stopPropagation();go({t:'check',ids:[x.id]});},'sm')
      ])
    ]);
  }

  function feedPane(){
    const list=ui.filter==='up'?recs.filter(function(r){return r.kind==='update';}):recs;
    let items;
    if(!S.sources.length){
      items=[empty('先到「来源」添加官网链接和关心的内容，之后这里会留下每次的检查记录。',btn('添加来源',function(){openSrcForm(null,null);},'primary sm'))];
    }else if(!recs.length){
      items=[empty('还没有检查记录。自动抓取暂未接入，可点「＋登记」把你在官网看到的更新记下来，卡片会和上次对比。')];
    }else if(!list.length){
      items=[empty('目前没有“有更新”的记录。')];
    }else{
      items=list.map(function(r){return recItem(r,null);});
    }
    return h('section',{class:'pane feed'},[
      h('div',{class:'ph'},[
        wide?h('span',{class:'pt'},['更新记录']):null,
        h('div',{class:'segs'+(wide?'':' push0')},[
          btn('全部 '+recs.length,function(){ui.filter='all';redraw();},'sm'+(ui.filter==='all'?' on':'')),
          btn('仅更新 '+nUp,function(){ui.filter='up';redraw();},'sm'+(ui.filter==='up'?' on':''))
        ]),
        btn('＋登记',function(){openRecForm(null,null);},'sm push',{disabled:!S.sources.length})
      ]),
      h('div',{class:'list'},items)
    ]);
  }
  function srcPane(){
    let items;
    if(!S.sources.length){
      items=[empty('还没有监控来源。填入官网链接和关心的内容（如价格、新功能、API 变更），并选择检查频率。',btn('＋ 添加来源',function(){openSrcForm(null,null);},'primary sm'))];
    }else{
      items=[h('div',{class:'note'},['频率与暂停状态已保存；自动定时检查暂未接入。'])].concat(S.sources.map(srcItem));
    }
    return h('section',{class:'pane srcs'},[
      wide?h('div',{class:'ph'},[h('span',{class:'pt'},['监控来源'])]):null,
      h('div',{class:'list'},items)
    ]);
  }
  function checkAllBtn(){
    return btn('立即检查',function(){go({t:'check',ids:'all'});},'primary',{disabled:!S.sources.length});
  }
  function header(){
    if(wide){
      const meta=S.sources.length+' 个来源'+(nPaused?' · '+nPaused+' 个暂停':'')+' · '+nUp+' 条更新';
      return h('div',{class:'hd'},[
        h('div',{class:'hdt'},[h('h1',{},['产品更新跟踪']),h('div',{class:'meta'},[meta])]),
        btn('＋ 添加来源',function(){openSrcForm(null,null);}),
        checkAllBtn()
      ]);
    }
    return h('div',{class:'hd'},[
      h('div',{class:'hdt'},[h('h1',{},['产品更新跟踪'])]),
      btn('＋',function(){openSrcForm(null,null);},'sm',{'aria-label':'添加来源',title:'添加来源'})
    ]);
  }
  function tabs(){
    return h('div',{class:'tabs'},[
      btn('更新 '+recs.length,function(){ui.tab='feed';redraw();},ui.tab==='feed'?'on':''),
      btn('来源 '+S.sources.length,function(){ui.tab='src';redraw();},ui.tab==='src'?'on':''),
      checkAllBtn()
    ]);
  }
  function home(){
    root.appendChild(header());
    if(!wide)root.appendChild(tabs());
    if(ui.msg)root.appendChild(h('div',{class:'err',role:'alert'},['⚠ '+ui.msg]));
    root.appendChild(h('div',{class:'body'},wide?[feedPane(),srcPane()]:[ui.tab==='src'?srcPane():feedPane()]));
  }


  function bar(title,onBack){
    return h('div',{class:'bar'},[btn('‹ 返回',onBack,'sm'),h('div',{class:'ttl'},[title])]);
  }
  function openSrcForm(id,from){
    const x=id?srcById[id]:null;
    go({t:'sform',id:id||null,from:from||null},{name:x?x.name:'',url:x?x.url:'',focus:x?(x.focus||''):'',freq:x?(x.freq||'weekly'):'weekly'});
  }
  function openRecForm(sid,from){
    if(!S.sources.length){ui.msg='请先添加一个监控来源';redraw();return;}
    const s0=sid&&srcById[sid]?sid:S.sources[0].id;
    go({t:'rform',from:from||null},{sid:s0,date:day(),kind:'update',title:'',changes:'',link:srcById[s0].url});
  }
  function field(f,draft){
    const cur=draft[f.key]==null?'':draft[f.key];
    let ctl;
    if(f.type==='select'){
      ctl=h('select',{class:'inp',onchange:function(e){
        const old=draft[f.key];
        draft[f.key]=e.target.value;
        if(f.onChange){f.onChange(e.target.value,old);}
      }},f.options.map(function(o){return h('option',{value:o.value},[o.label]);}));
      ctl.value=cur;
    }else if(f.type==='textarea'){
      ctl=h('textarea',{class:'inp',placeholder:f.ph||'',value:cur,oninput:function(e){draft[f.key]=e.target.value;}});
    }else{
      ctl=h('input',{class:'inp',type:f.type||'text',placeholder:f.ph||'',value:cur,
        oninput:function(e){draft[f.key]=e.target.value;},
        onkeydown:function(e){if(e.key==='Enter'&&f.enter){e.preventDefault();f.enter();}}});
    }
    return h('label',{class:'fld'+(f.type==='textarea'?' wide':'')},[h('span',{class:'lb'},[f.label+(f.req?' *':'')]),ctl]);
  }
  function formScreen(title,fields,draft,onSave,onBack,note){
    return h('div',{class:'screen'},[
      bar(title,onBack),
      h('div',{class:'scroll'},[
        note?h('div',{class:'note'},[note]):null,
        h('div',{class:'fields'},fields.map(function(f){return field(f,draft);}))
      ]),
      ui.err?h('div',{class:'err',role:'alert'},['⚠ '+ui.err]):null,
      h('div',{class:'foot'},[btn(ui.saving?'保存中…':'保存',onSave,'primary',{disabled:ui.saving}),btn('取消',onBack)])
    ]);
  }
  function saveFail(msg){
    return function(){ui.saving=false;ui.err=msg;redraw();};
  }
  function saveSource(){
    if(ui.saving)return;
    const sc=ui.screen,d=ui.draft||{};
    const url=(d.url||'').trim();
    if(!isUrl(url)){ui.err='请填写完整的官网链接，以 http:// 或 https:// 开头';redraw();return;}
    const name=(d.name||'').trim()||hostOf(url);
    const focus=(d.focus||'').trim();
    const freq=d.freq||'weekly';
    const id=sc.id||uid();
    const isNew=!sc.id;
    ui.saving=true;
    commit(function(s){
      const n=norm(s);
      const sources=isNew
        ?n.sources.concat([{id:id,name:name,url:url,focus:focus,freq:freq,paused:false,addedOn:day()}])
        :n.sources.map(function(x){return x.id===id?Object.assign({},x,{name:name,url:url,focus:focus,freq:freq}):x;});
      return Object.assign({},s,{sources:sources,records:n.records});
    },keep({screen:isNew?null:sc.from,tab:isNew?'src':ui.tab})).then(function(ok){
      if(ok===false)saveFail('没有保存成功，请重试')();
    }).catch(saveFail('保存失败，请重试'));
  }
  function saveRecord(){
    if(ui.saving)return;
    const sc=ui.screen,d=ui.draft||{};
    const src=srcById[d.sid];
    const title=(d.title||'').trim(),changes=(d.changes||'').trim(),link=(d.link||'').trim();
    let err=null;
    if(!src)err='请选择监控来源';
    else if(!isDate(d.date))err='请填写检查日期';
    else if(d.kind==='update'&&!title)err='有更新时请填写更新的标题或版本';
    else if(d.kind==='update'&&!isUrl(link))err='有更新时请附上出处链接（http:// 或 https:// 开头）';
    else if(link&&!isUrl(link))err='出处链接格式不正确';
    if(err){ui.err=err;redraw();return;}
    const rid=uid();
    const isUp=d.kind==='update';
    ui.saving=true;
    commit(function(s){
      const n=norm(s);
      const p=latestUpdate(n.records,d.sid,d.date);
      const rec={id:rid,sid:d.sid,sname:src.name,kind:isUp?'update':'nochange',date:d.date,title:isUp?title:'',changes:changes,link:link,prev:p?{title:p.title,date:p.date}:null,savedOn:day()};
      return Object.assign({},s,{sources:n.sources,records:n.records.concat([rec])});
    },keep({screen:sc.from,tab:'feed',filter:'all'})).then(function(ok){
      if(ok===false)saveFail('没有保存成功，请重试')();
    }).catch(saveFail('保存失败，请重试'));
  }
  function sourceForm(){
    const sc=ui.screen;
    return formScreen(sc.id?'编辑来源':'添加来源',[
      {key:'name',label:'名称（可不填）',ph:'例如：某产品更新日志',enter:saveSource},
      {key:'url',label:'官网链接',req:true,ph:'https://…',enter:saveSource},
      {key:'focus',label:'关心的内容',type:'textarea',ph:'例如：价格调整、新功能、API 变更'},
      {key:'freq',label:'检查频率',type:'select',options:FREQS}
