  function recScreen(sc){
    const r=S.records.filter(function(q){return q.id===sc.id;})[0];
    const isUp=r.kind==='update';
    const back=function(){go(sc.from||null);};
    const kids=[
      h('div',{class:'box'},[
        kv('来源',srcName(r)),
        kv('日期',r.date),
        kv('出处',r.link?link(r.link,r.link):'未填写')
