      bar(isUp?(r.title||'有更新'):'无更新',back),
      h('div',{class:'scroll'},kids),
      h('div',{class:'foot'},[btn('返回',back)])
    ]);
  }

  const sc=ui.screen;
  if(sc&&sc.t==='sform'&&ui.draft)root.appendChild(sourceForm());
  else if(sc&&sc.t==='rform'&&ui.draft&&S.sources.length)root.appendChild(recordForm());
  else if(sc&&sc.t==='check')root.appendChild(checkScreen(sc));
  else if(sc&&sc.t==='src'&&srcById[sc.id])root.appendChild(srcScreen(sc));
  else if(sc&&sc.t==='rec'&&S.records.some(function(q){return q.id===sc.id;}))root.appendChild(recScreen(sc));
  else home();
}

